// Coin change (fewest coins), bottom-up
function coinChange(coins, amount) {
  const INF = amount + 1, dp = new Array(amount + 1).fill(INF);
  dp[0] = 0;
  for (let a = 1; a <= amount; a++)
    for (const c of coins) if (c <= a) dp[a] = Math.min(dp[a], dp[a - c] + 1);
  return dp[amount] >= INF ? -1 : dp[amount];
}

// Longest common subsequence with two rows of space
function lcs(a, b) {
  let prev = new Array(b.length + 1).fill(0);
  for (let i = 1; i <= a.length; i++) {
    const cur = new Array(b.length + 1).fill(0);
    for (let j = 1; j <= b.length; j++)
      cur[j] = a[i - 1] === b[j - 1] ? prev[j - 1] + 1 : Math.max(prev[j], cur[j - 1]);
    prev = cur;
  }
  return prev[b.length];
}

// 0/1 knapsack in one array: iterate capacity DOWNWARD
function knapsack(weights, values, cap) {
  const dp = new Array(cap + 1).fill(0);
  weights.forEach((w, i) => { for (let c = cap; c >= w; c--) dp[c] = Math.max(dp[c], dp[c - w] + values[i]); });
  return dp[cap];
}

// LIS in O(n log n) with tails + binary search
function lis(nums) {
  const tails = [];
  for (const x of nums) {
    let lo = 0, hi = tails.length;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (tails[mid] < x) lo = mid + 1; else hi = mid; }
    tails[lo] = x;
  }
  return tails.length;
}

from functools import cache
from bisect import bisect_left

def coin_change(coins, amount):
    INF = float("inf")
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        dp[a] = min((dp[a - c] + 1 for c in coins if c <= a), default=INF)
    return -1 if dp[amount] == INF else dp[amount]

def coin_change_ways(coins, amount):            # combinations: coins in the OUTER loop
    dp = [1] + [0] * amount
    for c in coins:
        for a in range(c, amount + 1):
            dp[a] += dp[a - c]
    return dp[amount]

def edit_distance(a, b):
    m, n = len(a), len(b)
    dp = list(range(n + 1))                      # row for i = 0
    for i in range(1, m + 1):
        prev_diag, dp[0] = dp[0], i
        for j in range(1, n + 1):
            tmp = dp[j]
            dp[j] = prev_diag if a[i-1] == b[j-1] else 1 + min(dp[j], dp[j-1], prev_diag)
            prev_diag = tmp
    return dp[n]

def lis(nums):
    tails = []
    for x in nums:
        i = bisect_left(tails, x)
        if i == len(tails): tails.append(x)
        else: tails[i] = x
    return len(tails)

def house_robber(nums):
    prev2 = prev1 = 0
    for x in nums:
        prev2, prev1 = prev1, max(prev1, prev2 + x)
    return prev1

@cache
def climb(n):                                    # top-down memoisation
    return 1 if n <= 1 else climb(n - 1) + climb(n - 2)

int coinChange(int[] coins, int amount) {
    int[] dp = new int[amount + 1];
    Arrays.fill(dp, amount + 1);
    dp[0] = 0;
    for (int a = 1; a <= amount; a++)
        for (int c : coins) if (c <= a) dp[a] = Math.min(dp[a], dp[a - c] + 1);
    return dp[amount] > amount ? -1 : dp[amount];
}

int editDistance(String a, String b) {
    int m = a.length(), n = b.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 0; i <= m; i++) dp[i][0] = i;
    for (int j = 0; j <= n; j++) dp[0][j] = j;
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++)
            dp[i][j] = a.charAt(i-1) == b.charAt(j-1) ? dp[i-1][j-1]
                     : 1 + Math.min(dp[i-1][j-1], Math.min(dp[i-1][j], dp[i][j-1]));
    return dp[m][n];
}

int coinChange(vector<int>& coins, int amount) {
    vector<int> dp(amount + 1, amount + 1);
    dp[0] = 0;
    for (int a = 1; a <= amount; a++)
        for (int c : coins) if (c <= a) dp[a] = min(dp[a], dp[a - c] + 1);
    return dp[amount] > amount ? -1 : dp[amount];
}

int lengthOfLIS(vector<int>& nums) {
    vector<int> tails;
    for (int x : nums) {
        auto it = lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) tails.push_back(x); else *it = x;
    }
    return tails.size();
}

class Node:
    __slots__ = ("key", "val", "prev", "next")
    def __init__(self, key=0, val=0): self.key, self.val, self.prev, self.next = key, val, None, None

class LRUCache:
    def __init__(self, capacity: int):
        self.cap, self.map = capacity, {}
        self.head, self.tail = Node(), Node()             # sentinels
        self.head.next, self.tail.prev = self.tail, self.head

    def _remove(self, n): n.prev.next, n.next.prev = n.next, n.prev
    def _add_front(self, n):
        n.next, n.prev = self.head.next, self.head
        self.head.next.prev = n; self.head.next = n

    def get(self, key):
        n = self.map.get(key)
        if not n: return -1
        self._remove(n); self._add_front(n)               # now most recently used
        return n.val

    def put(self, key, value):
        if key in self.map:
            n = self.map[key]; n.val = value
            self._remove(n); self._add_front(n)
            return
        if len(self.map) == self.cap:
            lru = self.tail.prev
            self._remove(lru); del self.map[lru.key]      # remove the map entry too!
        n = Node(key, value); self.map[key] = n; self._add_front(n)

import random
class RandomizedSet:
    def __init__(self): self.vals, self.idx = [], {}
    def insert(self, v):
        if v in self.idx: return False
        self.idx[v] = len(self.vals); self.vals.append(v); return True
    def remove(self, v):
        if v not in self.idx: return False
        i, last = self.idx[v], self.vals[-1]
        self.vals[i], self.idx[last] = last, i             # move last element into the hole
        self.vals.pop(); del self.idx[v]; return True
    def get_random(self): return random.choice(self.vals)

// LRU using Map's insertion order (a JS Map iterates in insertion order)
class LRUCache {
  constructor(capacity) { this.cap = capacity; this.m = new Map(); }
  get(key) {
    if (!this.m.has(key)) return -1;
    const v = this.m.get(key);
    this.m.delete(key); this.m.set(key, v);               // re-insert = mark most recent
    return v;
  }
  put(key, value) {
    if (this.m.has(key)) this.m.delete(key);
    else if (this.m.size === this.cap) this.m.delete(this.m.keys().next().value);   // oldest key
    this.m.set(key, value);
  }
}

// Min stack
class MinStack {
  constructor() { this.s = []; this.mins = []; }
  push(x) { this.s.push(x); this.mins.push(this.mins.length ? Math.min(x, this.mins[this.mins.length - 1]) : x); }
  pop() { this.mins.pop(); return this.s.pop(); }
  top() { return this.s[this.s.length - 1]; }
  getMin() { return this.mins[this.mins.length - 1]; }
}

// Time-based key-value store with binary search
class TimeMap {
  constructor() { this.m = new Map(); }
  set(k, v, t) { if (!this.m.has(k)) this.m.set(k, []); this.m.get(k).push([t, v]); }
  get(k, t) {
    const a = this.m.get(k) ?? [];
    let lo = 0, hi = a.length;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (a[mid][0] <= t) lo = mid + 1; else hi = mid; }
    return lo ? a[lo - 1][1] : "";
  }
}

// LRU in a few lines with LinkedHashMap (access-order); know the manual version too
class LRUCache<K, V> extends LinkedHashMap<K, V> {
    private final int cap;
    LRUCache(int cap) { super(16, 0.75f, true); this.cap = cap; }      // true = access order
    @Override protected boolean removeEldestEntry(Map.Entry<K, V> eldest) { return size() > cap; }
}

class MinStack {
    private final Deque<int[]> st = new ArrayDeque<>();                // {value, minSoFar}
    void push(int x) { st.push(new int[]{x, st.isEmpty() ? x : Math.min(x, st.peek()[1])}); }
    void pop() { st.pop(); }
    int top() { return st.peek()[0]; }
    int getMin() { return st.peek()[1]; }
}

class LRUCache {
    int cap; list<pair<int,int>> items;                    // front = most recent
    unordered_map<int, list<pair<int,int>>::iterator> pos;
public:
    LRUCache(int c) : cap(c) {}
    int get(int key) {
        auto it = pos.find(key);
        if (it == pos.end()) return -1;
        items.splice(items.begin(), items, it->second);    // O(1) move to front, iterators stay valid
        return it->second->second;
    }
    void put(int key, int value) {
        auto it = pos.find(key);
        if (it != pos.end()) { it->second->second = value; items.splice(items.begin(), items, it->second); return; }
        if ((int)items.size() == cap) { pos.erase(items.back().first); items.pop_back(); }
        items.emplace_front(key, value); pos[key] = items.begin();
    }
};

import math, random

def gcd(a, b):
    while b: a, b = b, a % b
    return a                                           # same as math.gcd

def sieve(n):
    is_p = bytearray([1]) * (n + 1); is_p[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if is_p[i]:
            is_p[i*i::i] = bytearray(len(is_p[i*i::i]))   # mark multiples starting at i*i
    return [i for i, f in enumerate(is_p) if f]

def mod_pow(a, n, mod):
    result, a = 1, a % mod
    while n:
        if n & 1: result = result * a % mod
        a = a * a % mod
        n >>= 1
    return result                                      # pow(a, n, mod) is built in

MOD = 10**9 + 7
def mod_inv(b): return pow(b, MOD - 2, MOD)            # Fermat, MOD prime

def n_choose_k_mod(n, k, fact, inv_fact):              # after precomputing factorial tables
    if k < 0 or k > n: return 0
    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

def factorize(n):
    f, d = {}, 2
    while d * d <= n:
        while n % d == 0: f[d] = f.get(d, 0) + 1; n //= d
        d += 1
    if n > 1: f[n] = f.get(n, 0) + 1
    return f

def shuffle(a):                                        # Fisher-Yates
    for i in range(len(a) - 1, 0, -1):
        j = random.randint(0, i)
        a[i], a[j] = a[j], a[i]

def reservoir_sample(stream, k):
    res = []
    for i, x in enumerate(stream):
        if i < k: res.append(x)
        else:
            j = random.randint(0, i)                   # inclusive: probability k/(i+1) that j < k
            if j < k: res[j] = x
    return res

const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
const lcm = (a, b) => (a / gcd(a, b)) * b;

function countPrimes(n) {                       // primes strictly below n
  const composite = new Uint8Array(n);
  let count = 0;
  for (let i = 2; i < n; i++) {
    if (composite[i]) continue;
    count++;
    for (let j = i * i; j < n; j += i) composite[j] = 1;    // i*i may exceed 2^53 only for huge n
  }
  return count;
}

// Fast power with BigInt to avoid precision loss in modular multiplication
function modPow(base, exp, mod) {
  let result = 1n; base = BigInt(base) % mod; exp = BigInt(exp);
  while (exp > 0n) {
    if (exp & 1n) result = (result * base) % mod;
    base = (base * base) % mod; exp >>= 1n;
  }
  return result;
}

// Pow(x, n) with negative exponents
function myPow(x, n) {
  if (n < 0) { x = 1 / x; n = -n; }
  let result = 1;
  while (n > 0) { if (n & 1) result *= x; x *= x; n = Math.floor(n / 2); }   // Math.floor avoids 32-bit truncation
  return result;
}

long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }

long modPow(long base, long exp, long mod) {
    long result = 1; base %= mod;
    while (exp > 0) {
        if ((exp & 1) == 1) result = result * base % mod;    // fits in long when mod <= ~3e9
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

int countPrimes(int n) {
    if (n < 3) return 0;
    boolean[] composite = new boolean[n];
    int count = 0;
    for (int i = 2; i < n; i++) {
        if (composite[i]) continue;
        count++;
        for (long j = (long) i * i; j < n; j += i) composite[(int) j] = true;
    }
    return count;
}

long long modpow(long long a, long long n, long long mod) {
    long long r = 1; a %= mod;
    while (n) { if (n & 1) r = r * a % mod; a = a * a % mod; n >>= 1; }
    return r;
}

vector<int> sieve(int n) {
    vector<bool> comp(n + 1, false); vector<int> primes;
    for (int i = 2; i <= n; i++) {
        if (!comp[i]) { primes.push_back(i); for (long long j = 1LL * i * i; j <= n; j += i) comp[j] = true; }
    }
    return primes;
}
